/** 7 kỹ năng chấm trên lớp — nhãn theo tài liệu CEC ("Điểm thực hành trên lớp") */
export const SKILL_NAMES = ["Ngữ âm","Nghe","Nói","Đọc","Viết","Ngữ pháp","Từ vựng"] as const;

export type Attendance = "present" | "late" | "excused" | "absent";
export type ReportStatus = "draft" | "pending" | "approved";
export type HwStatus = "ontime" | "late" | "missing";

/** Student Report — từng học sinh × từng buổi. Nguồn của Monthly Report. */
export type StudentReport = {
  id: string; classId: number; session: number; date: string; studentId: string;
  attendance: Attendance;
  /** lý do nghỉ có phép, EC/QC nhập */
  absenceReason: string | null;
  status: ReportStatus;
  /** vắng thì mọi mục dưới bị khoá và để null */
  hwStatus: HwStatus | null;
  hwScore: number | null;
  skills: Record<string, number | null> | null;
  attitude: string | null;
  comment: string | null;
  by: string;
};

export type SkillRow = { name: string; now: number | null; prev: number | null; delta: number | null };

/** Monthly Report — AI tổng hợp từ các Student Report đã duyệt trong tháng */
export type MonthlyReport = {
  month: string; classId: number;
  reportCount: number; sessionTotal: number;
  present: number; late: number; absent: number; excused: number;
  attendRate: number;
  hwTotal: number; hwDone: number; hwLate: number;
  avgHw: number | null;
  skills: SkillRow[];
  status: ReportStatus;
};

