/* ---------------- Ba cờ báo cáo tháng ----------------
 * 🟢 đủ nguồn      — mọi buổi trong tháng đều có phiếu đã duyệt
 * 🟡 thiếu nguồn   — còn buổi chưa có phiếu duyệt, AI chưa đưa vào
 * 🔴 nghi trùng    — nhận xét giống tháng trước, vi phạm ràng buộc CEC
 *
 * Đặt ở đây để màn duyệt hàng loạt (`MonthlyBatch`) và màn danh sách lớp
 * (`MonthlyHub`) DÙNG CHUNG. Tính lại kiểu khác ở hai nơi là cách chắc chắn
 * để ra hai số cho cùng một thứ — lỗi đã mắc với "Đề có bản mới" (28 vs 6).
 */
export type CoBaoCao = "do" | "vang" | "xanh";

export function coCuaBaoCao(bc: MonthlyReport, daSoanLai = false): {
  co: CoBaoCao;
  lyDo: string;
} {
  const coPrev = bc.skills.some((k) => k.prev !== null);
  const khongDoi = bc.skills.filter((k) => k.delta === 0 || k.delta === null).length;
  const nghiTrung = coPrev && khongDoi >= Math.ceil(bc.skills.length * 0.7);
  const thieuNguon = bc.reportCount < bc.sessionTotal;

  if (nghiTrung && !daSoanLai)
    return {
      co: "do",
      lyDo: `Nghi trùng: ${khongDoi}/${bc.skills.length} kỹ năng không đổi so với tháng trước.`,
    };
  if (thieuNguon)
    return {
      co: "vang",
      lyDo: `Thiếu nguồn: chỉ có ${bc.reportCount}/${bc.sessionTotal} phiếu nhắc tên em.`,
    };
  return { co: "xanh", lyDo: "" };
}
